package server

import (
	"encoding/json"
	"fmt"
	"io"
)

// ExportOpenAPI registers the application's typed routes and writes the OpenAPI document
// generated by Huma. The zero-value services are registration placeholders: Huma reads the
// operation declarations without invoking handlers.
func ExportOpenAPI(writer io.Writer) error {
	server := newHTTPServer(nil)
	registerOperatorRoutes(server, nil)
	registerStatusRoutes(server, nil)

	encoded, err := json.MarshalIndent(server.api.OpenAPI(), "", "  ")
	if err != nil {
		return fmt.Errorf("encode Huma OpenAPI document: %w", err)
	}
	_, err = writer.Write(append(encoded, '\n'))
	return err
}
